/*
 * Export the Held UI as one self-contained, readable HTML file (scripts and CSS inlined, not
 * minified) for hosting the simulator on an ordinary website:
 *
 *   npm run held:export -- ../istari-arts-site/src/held_simulator.html
 *
 * Hosted away from a controller, the page runs as a simulator (its same-origin /json/held
 * probe fails). Connecting to a controller from an https page is blocked by browsers
 * (mixed content), so device control still needs the controller's own page or a local copy.
 */
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const inline = require('web-resource-inliner');

const out = process.argv[2];
if (!out) { console.error('usage: node tools/held/export.js <out.html>'); process.exit(1); }
const src = path.join(__dirname, '..', '..', 'wled00', 'data', 'held', 'index.htm');

inline.html({ fileContent: fs.readFileSync(src, 'utf8'), relativeTo: path.dirname(src), strict: true }, (err, html) => {
  if (err) throw err;
  fs.writeFileSync(out, html);
  console.log(`wrote ${out} (${html.length} bytes)`);
});
